// The home page: navigation on the left, the stories tray, the composer and
// the feed in the middle, sponsored content and contacts on the right.
import { Suspense, useEffect } from "react";
import { graphql, usePreloadedQuery } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import LoggingSurface from "LoggingSurface.react";
import UIErrorBoundary from "UIErrorBoundary.react";
import LeftRail from "LeftRail.react";
import RightRail from "RightRail.react";
import StoriesTray from "StoriesTray.react";
import InlineComposer from "InlineComposer.react";
import HomeFeed from "HomeFeed.react";
import FeedGlimmer from "FeedGlimmer.react";
import { emitStepEvent } from "Workload";

const styles = stylex.create({
  page: { display: "flex", justifyContent: "space-between", minHeight: "calc(100vh - 56px)", backgroundColor: colors.webWash },
  left: { position: "sticky", top: 56, alignSelf: "flex-start", width: 360, maxHeight: "calc(100vh - 56px)", overflowY: "auto", flexShrink: 1 },
  center: { flexGrow: 1, display: "flex", justifyContent: "center", paddingTop: 16, minWidth: 0 },
  column: { width: "100%", maxWidth: 590, paddingInline: 16 },
  right: { position: "sticky", top: 56, alignSelf: "flex-start", width: 360, maxHeight: "calc(100vh - 56px)", overflowY: "auto", flexShrink: 1 },
});

function FeedSection({ queryRef }) {
  const data = usePreloadedQuery(
    graphql`
      query HomePageFeedQuery($count: Int!) @preloadable {
        viewer {
          ...HomeFeed_viewer @arguments(count: $count)
        }
      }
    `,
    queryRef,
  );
  useEffect(() => {
    emitStepEvent("home-feed-rendered");
  }, []);
  return <HomeFeed viewer={data.viewer} />;
}

function TraySection({ queryRef }) {
  const data = usePreloadedQuery(
    graphql`
      query HomePageStoriesTrayQuery @preloadable {
        viewer {
          stories_tray {
            ...StoriesTray_tray
          }
        }
      }
    `,
    queryRef,
  );
  return data.viewer?.stories_tray ? <StoriesTray tray={data.viewer.stories_tray} /> : null;
}

function LeftRailSection({ queryRef }) {
  const data = usePreloadedQuery(
    graphql`
      query HomePageLeftRailQuery @preloadable {
        viewer {
          left_rail {
            ...LeftRail_rail
          }
        }
      }
    `,
    queryRef,
  );
  return data.viewer?.left_rail ? <LeftRail rail={data.viewer.left_rail} /> : null;
}

function RightRailSection({ queryRef }) {
  const data = usePreloadedQuery(
    graphql`
      query HomePageRightRailQuery @preloadable {
        viewer {
          right_rail {
            ...RightRail_rail
          }
        }
      }
    `,
    queryRef,
  );
  return data.viewer?.right_rail ? <RightRail rail={data.viewer.right_rail} /> : null;
}

function ComposerSection({ queryRef }) {
  const data = usePreloadedQuery(
    graphql`
      query HomePageInlineComposerQuery @preloadable {
        viewer {
          ...InlineComposer_viewer
        }
      }
    `,
    queryRef,
  );
  return data.viewer ? <InlineComposer viewer={data.viewer} /> : null;
}

export default function HomePage({ queries }) {
  return (
    <LoggingSurface name="home">
      <div {...stylex.props(styles.page)}>
        <div role="navigation" aria-label="Shortcuts" {...stylex.props(styles.left)}>
          <UIErrorBoundary name="left_rail">
            <Suspense fallback={null}>
              <LeftRailSection queryRef={queries.leftRail} />
            </Suspense>
          </UIErrorBoundary>
        </div>
        <div role="main" {...stylex.props(styles.center)}>
          <div {...stylex.props(styles.column)}>
            <UIErrorBoundary name="stories_tray">
              <Suspense fallback={null}>
                <TraySection queryRef={queries.tray} />
              </Suspense>
            </UIErrorBoundary>
            <UIErrorBoundary name="composer">
              <Suspense fallback={null}>
                <ComposerSection queryRef={queries.composer} />
              </Suspense>
            </UIErrorBoundary>
            <UIErrorBoundary name="feed">
              <Suspense fallback={<FeedGlimmer />}>
                <FeedSection queryRef={queries.feed} />
              </Suspense>
            </UIErrorBoundary>
          </div>
        </div>
        <div role="complementary" aria-label="Sponsored and contacts" {...stylex.props(styles.right)}>
          <UIErrorBoundary name="right_rail">
            <Suspense fallback={null}>
              <RightRailSection queryRef={queries.rightRail} />
            </Suspense>
          </UIErrorBoundary>
        </div>
      </div>
    </LoggingSurface>
  );
}
