// The news feed: a paginated connection whose edges the server streams, a
// few stories at a time. Scrolling near the end triggers the next page
// through an IntersectionObserver, as on the reference site.
import { useCallback, useEffect, useRef } from "react";
import { graphql, usePaginationFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import FeedUnit from "FeedUnit.react";
import FeedVirtualizedUnit from "FeedVirtualizedUnit.react";
import FeedGlimmer from "FeedGlimmer.react";
import LoggingSurface from "LoggingSurface.react";
import { emitStepEvent } from "Workload";
import PerfLogger from "PerfLogger";
import { HOME_FEED_PAGE_SIZE } from "HomeFeedConfig";

// How far below the viewport the next page starts loading.
const PREFETCH_DISTANCE = 600;

const styles = stylex.create({
  sentinel: { height: 1 },
});

export default function HomeFeed({ viewer }) {
  const { data, loadNext, hasNext, isLoadingNext } = usePaginationFragment(
    graphql`
      fragment HomeFeed_viewer on Viewer
      @refetchable(queryName: "HomeFeedPaginationQuery")
      @argumentDefinitions(count: { type: "Int", defaultValue: 3 }, cursor: { type: "String" }) {
        news_feed(first: $count, after: $cursor) @stream_connection(key: "HomeFeed_news_feed", initial_count: 1) {
          edges {
            cursor
            category
            feed_backend_data {
              section_id
              logging_position
            }
            node {
              id
              ...FeedUnit_unit
            }
          }
        }
      }
    `,
    viewer,
  );
  const sentinel = useRef(null);
  const state = useRef(null);
  state.current = { hasNext, isLoadingNext, loadNext };
  // Loads the next page when the sentinel is near the viewport, checked when
  // it moves into view and when a load finishes (the page info arrives in a
  // deferred payload, after the edges).
  const maybeLoadNext = useCallback(() => {
    const { hasNext: more, isLoadingNext: loading, loadNext: next } = state.current;
    const near = sentinel.current !== null && sentinel.current.getBoundingClientRect().top <= window.innerHeight + PREFETCH_DISTANCE;
    if (!near || !more || loading) {
      return;
    }
    const instance = PerfLogger.newInstanceKey();
    PerfLogger.markerStart("feed_pagination", instance);
    next(HOME_FEED_PAGE_SIZE, {
      onComplete: () => {
        PerfLogger.markerEnd("feed_pagination", "success", instance);
        emitStepEvent("feed-page-loaded");
      },
    });
  }, []);
  useEffect(() => {
    const observer = new IntersectionObserver(
      () => maybeLoadNext(),
      { rootMargin: `0px 0px ${PREFETCH_DISTANCE}px 0px` },
    );
    observer.observe(sentinel.current);
    return () => observer.disconnect();
  }, [maybeLoadNext]);
  useEffect(() => {
    if (!isLoadingNext) {
      maybeLoadNext();
    }
  }, [hasNext, isLoadingNext, maybeLoadNext]);
  const edges = data.news_feed?.edges ?? [];
  return (
    <LoggingSurface name="news_feed" as="div">
      <h2 style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0 0 0 0)" }}>News Feed posts</h2>
      <div role="feed" aria-busy={isLoadingNext} data-testid="news-feed">
        {edges.map((edge, i) =>
          edge?.node ? (
            <FeedVirtualizedUnit key={edge.node.id} position={i}>
              <FeedUnit unit={edge.node} position={i} />
            </FeedVirtualizedUnit>
          ) : null,
        )}
      </div>
      {isLoadingNext || hasNext ? <FeedGlimmer /> : null}
      <div ref={sentinel} data-testid="feed-sentinel" {...stylex.props(styles.sentinel)} />
    </LoggingSurface>
  );
}
